using System.Net;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using RestaurantManagement.API.Data;
using RestaurantManagement.API.Models;
using RestaurantManagement.Web.Models;
using RestaurantManagement.Web.Services;

public static class Week10BookingSmoke
{
    public static async Task Run(RestaurantDbContext db, HttpClient admin, Func<HttpClient> newClient, Func<string,string,string> hidden, Action<bool,string> check)
    {
        async Task<string> Get(HttpClient client, string path) { using var response = await client.GetAsync(path); check(response.StatusCode == HttpStatusCode.OK, "W10 GET " + path); return await response.Content.ReadAsStringAsync(); }
        async Task<HttpStatusCode> Post(HttpClient client, string path, string html, Dictionary<string,string> fields) {
            fields["__RequestVerificationToken"] = hidden(html, "__RequestVerificationToken");
            using var request = new HttpRequestMessage(HttpMethod.Post,path) { Content = new FormUrlEncodedContent(fields) };
            request.Headers.Add("X-Requested-With","XMLHttpRequest"); using var response = await client.SendAsync(request); return response.StatusCode;
        }
        string Version(object entity) => Convert.ToBase64String((byte[])db.Entry(entity).Property("RowVersion").CurrentValue!);
        var day = DateOnly.FromDateTime(TableService.VietnamNow).AddDays(10);
        var evening = day.ToDateTime(new(18,30));
        check(ReservationSchedule.Slots.Count == 2 && ReservationSchedule.Validate(evening,TableService.VietnamNow) is null, "Free 18:30 arrival accepted in one of two shifts");
        check(ReservationSchedule.Validate(day.ToDateTime(new(16,0)),TableService.VietnamNow) is null, "16:00 is within continuous service, not a fabricated afternoon closure");
        check(ReservationSchedule.Validate(day.ToDateTime(new(10,59)),TableService.VietnamNow) is not null && ReservationSchedule.Validate(day.ToDateTime(new(22,0)),TableService.VietnamNow) is not null, "Actual opening and closing boundaries are enforced");
        check(ReservationSchedule.Match(day.ToDateTime(new(16,0)))?.Id=="trua"&&ReservationSchedule.EndOf(day.ToDateTime(new(16,0)))==TableService.VietnamTime(day.ToDateTime(new(17,0))), "Afternoon arrivals belong to a management shift without an operating-hours gap");
        var suggestionNow=day.ToDateTime(new(20,6));
        var lateSuggestions=ReservationSchedule.QuickArrivals(day,suggestionNow);
        check(lateSuggestions.SequenceEqual(new[]{day.ToDateTime(new(20,45))}), "Late-day quick choice contains only the remaining shift and respects the 30-minute lead");
        check(ReservationSchedule.QuickArrivals(day.AddDays(1),suggestionNow).Select(x=>x.Hour).SequenceEqual(new[]{11,17}),"Future date offers two shift shortcuts before the guest has typed a time");
        check(ReservationSchedule.Validate(day.AddDays(1).ToDateTime(new(16,7)),suggestionNow) is null,"Arbitrary 16:07 is valid independently of shift shortcuts");
        check(ReservationSchedule.QuickArrivals(day,day.ToDateTime(new(21,45))).Count==0,"After the last online arrival no expired shortcuts are displayed");
        check(ReservationSchedule.QuickArrivals(day,day.ToDateTime(new(21,45)),-15).Count==1,"Reception can suggest a near-real-time arrival rather than inheriting the online 30-minute restriction");
        check(ReservationSchedule.EndOf(evening) == TableService.VietnamTime(day.ToDateTime(new(22,0))), "Stored end is closing time, not arrival plus hours");
        var service = new TableService(db,new PreorderService(db,new OrderService(db)));
        var area = new KhuVuc { TenKhuVuc = "W10-TEST-AREA" };
        var a = new BanAn { MaBan="W10-TEST-A", KhuVuc=area, SoChoNgoi=4, TrangThai=TrangThaiBan.CanDon };
        var b = new BanAn { MaBan="W10-TEST-B", KhuVuc=area, SoChoNgoi=4, TrangThai=TrangThaiBan.SanSang };
        db.BanAn.AddRange(a,b); await db.SaveChangesAsync();
        var orphan=new BanAn{MaBan="W10-ORPHAN",KhuVucId=area.Id,SoChoNgoi=1,TrangThai=TrangThaiBan.CanDon};db.BanAn.Add(orphan);await db.SaveChangesAsync();
        check((await service.PhysicalBusyTables(DateTimeOffset.UtcNow)).Contains(orphan.Id),"Unknown-date orphan dirty table stays blocked today until staff checks it");
        check(!(await service.PhysicalBusyTables(TableService.VietnamTime(evening))).Contains(orphan.Id),"Unknown old physical flag cannot block another date");
        DatBan Booking(string code,DateTime arrival,TrangThaiDatBan state) => new() { MaDatBan=code,HoTenLienHe=code,SoDienThoaiLienHe="0901234567",SoNguoiLon=4,LaKhachTrucTiep=true,KhuVucUuTienId=area.Id,ThoiDiemTao=DateTimeOffset.UtcNow,GioDen=TableService.VietnamTime(arrival),GioKetThucDuKien=ReservationSchedule.EndOf(arrival),TrangThai=state };
        var nearbyDay=day.AddDays(60); var nearbyPreferred=nearbyDay.ToDateTime(new(16,0));
        var nearest=await service.AvailableSlots(nearbyDay,4,area.Id,preferredArrival:nearbyPreferred);
        check(nearest.Error is null&&nearest.Slots.Select(x=>x.Label).SequenceEqual(new[]{"Ca trưa · 11:00","Ca tối · 17:00"}),"Future date offers one earliest quick choice per management shift");
        check((await service.AvailableSlots(nearbyDay,4,area.Id,preferredArrival:nearbyPreferred.AddMinutes(7))).Slots.SequenceEqual(nearest.Slots),"Typing another hour does not recenter or multiply shift suggestions");
        var eveningBlockA=Booking("W10-NEARBY-BLOCK-A",nearbyDay.ToDateTime(new(18,0)),TrangThaiDatBan.DaXacNhan);
        var eveningBlockB=Booking("W10-NEARBY-BLOCK-B",nearbyDay.ToDateTime(new(18,0)),TrangThaiDatBan.DaXacNhan);
        eveningBlockA.Ban.Add(new(){BanAnId=a.Id});eveningBlockB.Ban.Add(new(){BanAnId=b.Id});db.DatBan.AddRange(eveningBlockA,eveningBlockB);await db.SaveChangesAsync();
        var nearBoundary=await service.AvailableSlots(nearbyDay,4,area.Id,preferredArrival:nearbyDay.ToDateTime(new(16,45)));
        check(nearBoundary.Slots.Count==2&&nearBoundary.Slots[0].Available&&!nearBoundary.Slots[1].Available,"Full evening is marked unavailable while lunch remains a separate usable shortcut");
        check((await service.CheckAvailability(nearbyDay.ToDateTime(new(18,30)),4,area.Id)).Available==false,"Typed arrival in a full shift is rejected independently of suggestions");
        check((await service.AvailableSlots(nearbyDay,20,area.Id,preferredArrival:nearbyPreferred)).Slots.All(x=>!x.Available),"Quick choices respect party size rather than summing small tables");
        check((await service.AvailableSlots(nearbyDay,4,area.Id,preferredArrival:nearbyPreferred.AddDays(1))).Error is not null,"Mismatched date/time cannot return another day's availability");
        var previous = Booking("W10-OLD-DAY",day.AddDays(-1).ToDateTime(new(18,0)),TrangThaiDatBan.DaNhanBan);
        previous.ThoiDiemNhanBan=previous.GioDen; previous.Ban.Add(new() { BanAnId=a.Id }); db.DatBan.Add(previous); await db.SaveChangesAsync();
        check(await service.HasCapacity(TableService.VietnamTime(evening),ReservationSchedule.EndOf(evening),4,area.Id,false),"Old-day uncleaned state cannot lock another date");
        check(!await service.HasCapacity(TableService.VietnamTime(evening),ReservationSchedule.EndOf(evening),8,area.Id,false),"Two small tables cannot falsely satisfy a one-table reservation");
        var first=Booking("W10-FIRST",evening,TrangThaiDatBan.ChoXacNhan); db.DatBan.Add(first); await db.SaveChangesAsync();
        check(await service.Assign(first.Id,[a.Id,b.Id],Version(first),null) is not null&&!await db.ChiTietDatBan.AnyAsync(x=>x.DatBanId==first.Id),"Forged multi-table assignment is rejected without writing links");
        check(await service.Assign(first.Id,[b.Id],Version(first),null) is null,"First fitting table can be assigned");
        check(await service.Assign(first.Id,[a.Id],Version(first),null) is null,"Future booking can use stale global table status from an old date");
        check(await db.ChiTietDatBan.CountAsync(x=>x.DatBanId==first.Id)==1&&await db.ChiTietDatBan.AnyAsync(x=>x.DatBanId==first.Id&&x.BanAnId==a.Id),"Switching table replaces the previous link rather than retaining both");
        var later=Booking("W10-LATER",day.ToDateTime(new(20,30)),TrangThaiDatBan.ChoXacNhan);db.DatBan.Add(later);await db.SaveChangesAsync();
        check(await service.Assign(later.Id,[a.Id],Version(later),null) is not null,"Same table cannot take a second turn in the same shift");
        check(await service.Assign(later.Id,[b.Id],Version(later),null) is null,"A different table can take the later arrival");
        check(!await service.HasCapacity(TableService.VietnamTime(evening),ReservationSchedule.EndOf(evening),4,area.Id,false),"Forecast closes a shift when all suitable tables already have turns");
        check(await service.HasCapacity(TableService.VietnamTime(day.ToDateTime(new(12,0))),ReservationSchedule.EndOf(day.ToDateTime(new(12,0))),4,area.Id,false),"Dinner bookings do not block lunch on the same day");
        var board=await Get(admin,$"/SoDoBan?ngay={day:yyyy-MM-dd}&ca=toi&khuVucId={area.Id}");
        check(board.Contains(first.MaDatBan)&&board.Contains(later.MaDatBan)&&!board.Contains(previous.MaDatBan),"Floor board loads exactly the selected day rather than all old table history");
        check(!board.Contains("Sau 3 tiếng")&&board.Contains("một lượt"),"Floor board explains shift turns without a three-hour countdown");
        var assignHtml=System.Net.WebUtility.HtmlDecode(await Get(admin,$"/SoDoBan?datBanId={first.Id}&dialog=true"));
        check(assignHtml.Contains("type=\"radio\" name=\"banAnIds\"")&&!assignHtml.Contains("type=\"checkbox\" name=\"banAnIds\""),"Assignment uses a native mutually exclusive radio group");
        check(assignHtml.Contains("Bàn của lịch này")&&assignHtml.Contains(later.HoTenLienHe),"Assignment distinguishes the current reservation from another guest's schedule");
        var edit = await Get(admin,"/QuanLyDatBan/DoiGio/"+first.Id+"?dialog=true");
        var original=Version(first);
        var target=day.AddDays(1).ToDateTime(new(18,45));
        check(await Post(admin,"/QuanLyDatBan/DoiGio",edit,new() { ["Id"]=first.Id.ToString(),["RowVersion"]=original,["Code"]=first.MaDatBan,["Customer"]=first.HoTenLienHe,["GioDen"]=target.ToString("yyyy-MM-ddTHH:mm"),["LyDo"]="Khách đổi ngày" })==HttpStatusCode.OK,"Reception reschedules an arbitrary time by AJAX");
        await db.Entry(first).ReloadAsync();
        check(first.GioDen==TableService.VietnamTime(target)&&first.MaDatBan=="W10-FIRST"&&first.TienCocDaNop==0,"Rescheduling preserves code and deposit");
        check(await Post(admin,"/QuanLyDatBan/DoiGio",edit,new() { ["Id"]=first.Id.ToString(),["RowVersion"]=original,["Code"]=first.MaDatBan,["Customer"]=first.HoTenLienHe,["GioDen"]=target.ToString("yyyy-MM-ddTHH:mm"),["LyDo"]="Stale" })==HttpStatusCode.Conflict,"Stale rescheduling cannot overwrite a new schedule");
        check(await service.Reschedule(first.Id,Version(first),evening,"Trùng ca",null) is null,"Own original table is free after moving away");
        var secondRequest=Booking("W10-CONFLICT",target,TrangThaiDatBan.ChoXacNhan);db.DatBan.Add(secondRequest);await db.SaveChangesAsync();
        check(await service.Assign(secondRequest.Id,[a.Id],Version(secondRequest),null) is null,"Another booking may claim the vacated date");
        check(await service.Reschedule(first.Id,Version(first),target,"Đổi vào ca đã có khách",null) is not null,"Reschedule rejects an already occupied target shift");
        await db.Entry(first).ReloadAsync();check(first.GioDen==TableService.VietnamTime(evening),"Failed reschedule keeps the original time");

        await Week10DemoSetup.InitializeAsync(db);var count=await db.DatBan.CountAsync(x=>x.MaDatBan.StartsWith("W10-20"));await Week10DemoSetup.InitializeAsync(db);
        check(count==2&&await db.DatBan.CountAsync(x=>x.MaDatBan.StartsWith("W10-20"))==count,"Lunch/dinner demo creation is idempotent");
        var dish=await db.MonAn.Include(x=>x.Sizes).ThenInclude(x=>x.DinhMuc).SingleAsync(x=>x.TenMon=="Gỏi ngó sen tôm thịt");
        check(dish.Sizes.Count(x=>x.DinhMuc.Count>0)>=3,"Seeded real dish includes recipes for all three sizes");
        var size=dish.Sizes.OrderBy(x=>x.GiaBan).First();
        first.MonDatTruoc.Add(new() { MonAnId=dish.Id,MonAnSizeId=size.Id,TenMonLucDat=dish.TenMon,TenSizeLucDat=size.TenSize,SoLuong=2,DonGiaThoaThuan=size.GiaBan });await db.SaveChangesAsync();
        var plan=await new ReservationPlanningService(db).Build(day,day,"toi",false);
        var ingredient=await db.NguyenLieu.SingleAsync(x=>x.TenNguyenLieu=="Ngó sen");
        var expected=size.DinhMuc.Single(x=>x.NguyenLieuId==ingredient.Id).SoLuong*2;
        check(plan.Ingredients.Single(x=>x.Name=="Ngó sen").Required==expected,"Planning multiplies exact selected-size recipe by preorder quantity");
        check(plan.Rows.Sum(x=>x.Tables)==2&&plan.WithoutFood==1,"Planning distinguishes table turns and bookings without food");
        var missingSize=new MonAnSize{MonAnId=dish.Id,TenSize="Chưa định mức",GiaBan=100000,DangSuDung=true};db.MonAnSize.Add(missingSize);await db.SaveChangesAsync();
        later.MonDatTruoc.Add(new(){MonAnId=dish.Id,MonAnSizeId=missingSize.Id,TenMonLucDat=dish.TenMon,TenSizeLucDat=missingSize.TenSize,SoLuong=3,DonGiaThoaThuan=missingSize.GiaBan});await db.SaveChangesAsync();
        var missingPlan=await new ReservationPlanningService(db).Build(day,day,"toi",false);
        check(missingPlan.Warnings.Any(x=>x.Contains(later.MaDatBan))&&missingPlan.Ingredients.Single(x=>x.Name=="Ngó sen").Required==expected,"Missing recipe is warned about without borrowing another size or inventing demand");
        var pastDay=DateOnly.FromDateTime(TableService.VietnamNow).AddDays(-1);
        var past=Booking("W10-PAST-NOT-RECEIVED",pastDay.ToDateTime(new(18,0)),TrangThaiDatBan.DaXacNhan);
        past.MonDatTruoc.Add(new(){MonAnId=dish.Id,MonAnSizeId=size.Id,TenMonLucDat=dish.TenMon,TenSizeLucDat=size.TenSize,SoLuong=2,DonGiaThoaThuan=size.GiaBan});db.DatBan.Add(past);await db.SaveChangesAsync();
        var pastPlan=await new ReservationPlanningService(db).Build(pastDay,pastDay,"toi",false);
        check(pastPlan.Rows.Sum(x=>x.Reservations)==1&&pastPlan.Ingredients.Count==0,"Past unreceived reservations remain in historical counts but never create a new purchasing demand");
        await Get(admin,$"/ThongKeDatBan?tuNgay={day:yyyy-MM-dd}&ca=toi");
        using(var invalid=await admin.GetAsync("/ThongKeDatBan?tuNgay=9999-12-31&cheDo=tuan"))check(invalid.StatusCode==HttpStatusCode.BadRequest,"Out-of-range week filter returns validation error rather than a server crash");
        using var customer=newClient(); var login=await Get(customer,"/Account/Login");
        check(await Post(customer,"/Account/Login",login,new(){["Email"]="khach.demo@example.test",["Password"]="Demo@2026!"})==HttpStatusCode.Redirect,"Customer login uses the existing redirect contract");
        using(var denied=await customer.GetAsync("/ThongKeDatBan")) check(denied.StatusCode!=HttpStatusCode.OK,"Customer cannot inspect kitchen planning or customer contacts");
        var customerForm=await Get(customer,"/DatBan");
        check(customerForm.Contains("type=\"datetime-local\"")&&customerForm.Contains("data-time-suggestions")&&customerForm.Contains("for=\"inputThoiGianDen\""),"Customer can type a correctly labelled free time and use optional suggestions");
        check(customerForm.Contains("data-server-now=")&&customerForm.Contains("data-time-error"),"Customer form supports immediate server-clock-based time validation");
        var onlineArrival=day.AddDays(30).ToDateTime(new(18,45));
        var requestId=hidden(customerForm[customerForm.IndexOf("id=\"formDatBan\"",StringComparison.Ordinal)..],"RequestId");
        var onlineFields=new Dictionary<string,string>{["HoTen"]="W10-ONLINE",["SoDienThoai"]="0901234567",["SoNguoi"]="4",["MaKhuVuc"]=area.Id.ToString(),["ThoiGianDen"]=onlineArrival.ToString("yyyy-MM-ddTHH:mm"),["RequestId"]=requestId};
        check(await Post(customer,"/DatBan",customerForm,onlineFields)==HttpStatusCode.OK,"Direct customer POST accepts 18:45, not only suggested times");
        var online=await db.DatBan.SingleAsync(x=>x.HoTenLienHe=="W10-ONLINE");
        check(online.TrangThai==TrangThaiDatBan.ChoCoc&&online.TienCocDaNop==0&&online.TienCocYeuCau>0,"Free-time booking still requires real deposit verification");
        var deadline=online.HanThanhToanCoc;var required=online.TienCocYeuCau;
        check(await service.Reschedule(online.Id,Version(online),onlineArrival.AddDays(1),"Khách đổi lịch",null) is null,"Unpaid but valid online hold may be rescheduled");
        check(online.HanThanhToanCoc==deadline&&online.TienCocYeuCau==required,"Rescheduling does not extend the payment deadline or reset the deposit");
        using(var availability=await customer.GetAsync($"/DatBan/KhungGio?ngay={day.AddDays(30):yyyy-MM-dd}&gioDen={day.AddDays(30):yyyy-MM-dd}T16:00&soNguoi=4&maKhuVuc={area.Id}")) {
            using var json=JsonDocument.Parse(await availability.Content.ReadAsStringAsync());
            check(availability.IsSuccessStatusCode&&json.RootElement.GetProperty("available").GetBoolean()&&json.RootElement.GetProperty("slots").EnumerateArray().Select(x=>x.GetProperty("label").GetString()).SequenceEqual(new[]{"Ca trưa · 11:00","Ca tối · 17:00"}),"Customer availability returns two shift shortcuts while accepting a separately typed 16:00");
        }
        onlineFields["RequestId"]=Guid.NewGuid().ToString();onlineFields["HoTen"]="W10-ONLINE-AFTERNOON";onlineFields["ThoiGianDen"]=day.AddDays(30).ToDateTime(new(16,7)).ToString("yyyy-MM-ddTHH:mm");
        check(await Post(customer,"/DatBan",customerForm,onlineFields)==HttpStatusCode.OK,"Direct customer submission accepts 16:00, not only a UI-only workaround");
        var afternoonBooking=await db.DatBan.SingleAsync(x=>x.HoTenLienHe=="W10-ONLINE-AFTERNOON");
        check(afternoonBooking.GioDen.ToOffset(TimeSpan.FromHours(7)).TimeOfDay==new TimeSpan(16,7,0)&&afternoonBooking.TrangThai==TrangThaiDatBan.ChoCoc,"Afternoon request preserves arbitrary 16:07 and still requires deposit verification");
        check(await service.Reschedule(afternoonBooking.Id,Version(afternoonBooking),day.AddDays(32).ToDateTime(new(16,15)),"Khách đổi giờ chiều",null) is null,"Reception rescheduling also accepts non-suggested afternoon times");
        var beforeInvalid=await db.DatBan.CountAsync();onlineFields["RequestId"]=Guid.NewGuid().ToString();onlineFields["ThoiGianDen"]=day.AddDays(30).ToDateTime(new(10,59)).ToString("yyyy-MM-ddTHH:mm");
        check(await Post(customer,"/DatBan",customerForm,onlineFields)!=HttpStatusCode.OK&&await db.DatBan.CountAsync()==beforeInvalid,"Forged closed-hour request creates neither booking nor deposit hold");
        onlineFields["RequestId"]=Guid.NewGuid().ToString();onlineFields.Remove("ThoiGianDen");
        check(await Post(customer,"/DatBan",customerForm,onlineFields)!=HttpStatusCode.OK&&await db.DatBan.CountAsync()==beforeInvalid,"Missing posted arrival cannot silently use a view-model default");
        var race1=Booking("W10-RACE-1",day.AddDays(20).ToDateTime(new(17,30)),TrangThaiDatBan.ChoXacNhan);
        var race2=Booking("W10-RACE-2",day.AddDays(20).ToDateTime(new(20,0)),TrangThaiDatBan.ChoXacNhan);
        db.DatBan.AddRange(race1,race2);await db.SaveChangesAsync();
        var raceResults=await Task.WhenAll(new[]{race1,race2}.Select(r=>Post(admin,"/QuanLyDatBan/XacNhan",edit,new(){["datBanId"]=r.Id.ToString(),["banAnIds"]=a.Id.ToString(),["rowVersion"]=Version(r)})));
        check(raceResults.Count(x=>x==HttpStatusCode.OK)==1&&raceResults.Count(x=>x==HttpStatusCode.Conflict)==1,"Concurrent different arrival times in one shift still allocate the table once");
        first.TrangThai=TrangThaiDatBan.DaNhanBan;first.ThoiDiemNhanBan=first.GioDen;first.ThoiDiemKetThuc=first.GioDen.AddMinutes(30);a.TrangThai=TrangThaiBan.SanSang;await db.SaveChangesAsync();
        var afterFinish=Booking("W10-SAME-SHIFT-AGAIN",day.ToDateTime(new(21,0)),TrangThaiDatBan.ChoXacNhan);db.DatBan.Add(afterFinish);await db.SaveChangesAsync();
        check(await service.Assign(afterFinish.Id,[a.Id],Version(afterFinish),null) is not null,"Completed and cleaned table does not sell a second turn within the same shift");

        var today=TableService.VietnamNow;var actualStart=TableService.VietnamTime(today.AddHours(-4));
        var active=Booking("W10-ACTIVE",day.ToDateTime(new(18,0)),TrangThaiDatBan.DaNhanBan);
        active.GioDen=TableService.VietnamTime(today.Date.AddMinutes(1));active.GioKetThucDuKien=TableService.VietnamTime(today.Date.AddDays(1));active.ThoiDiemNhanBan=actualStart;active.Ban.Add(new(){BanAnId=b.Id});b.TrangThai=TrangThaiBan.DangPhucVu;db.DatBan.Add(active);await db.SaveChangesAsync();
        check(await service.CloseOverdue(active.Id) is not null,"Elapsed four hours never ends a service automatically");
        var reminderHtml=System.Net.WebUtility.HtmlDecode(await Get(admin,"/SoDoBan"));
        check(reminderHtml.Contains("Đã phục vụ hơn 3 tiếng"),"Four-hour service shows a reminder without force closing");
        await service.CompletePaidService(active.Id);await db.Entry(active).ReloadAsync();check(active.ThoiDiemKetThuc is null,"Unpaid party remains serving regardless of elapsed time");
        var staff=await db.NhanVien.FirstAsync();
        var bill=new HoaDon { MaHoaDon="W10-PAY",DatBanId=active.Id,NhanVienId=staff.Id,ThoiDiemLap=DateTimeOffset.UtcNow,TrangThai=TrangThaiHoaDon.ChuaThanhToan,TongTienHang=100000 };
        bill.ChiTiet.Add(new(){MonAnId=dish.Id,MonAnSizeId=size.Id,TenMonLucBan=dish.TenMon,TenSizeLucBan=size.TenSize,SoLuong=1,DonGia=100000,ThoiDiemGoi=DateTimeOffset.UtcNow,TrangThai=TrangThaiCheBien.DaPhucVu});db.HoaDon.Add(bill);await db.SaveChangesAsync();
        b.TrangThai=TrangThaiBan.CanDon;await db.SaveChangesAsync();
        check(await service.ChangeTable(b.Id,Version(b),true) is not null,"Changing a physical flag to Needs cleaning cannot bypass an unpaid active bill");
        b.TrangThai=TrangThaiBan.DangPhucVu;await db.SaveChangesAsync();
        check(await new OrderService(db).ProcessPaymentAsync(new(){Id=bill.Id,RowVersion=Version(bill),BookingRowVersion=Version(active),PhuongThuc=PhuongThucThanhToan.TienMat,TienKhachDua=100000},staff.Id) is null,"Payment completes through the existing shared payment service");
        await db.Entry(active).ReloadAsync();await db.Entry(b).ReloadAsync();check(active.ThoiDiemKetThuc is not null&&b.TrangThai==TrangThaiBan.SanSang,"Final payment completes service directly, with no separate cleaning stage");
        check(await service.ChangeTable(b.Id,Version(b),true) is not null,"Already completed table rejects repeated confirmation");

        var legacyTable=new BanAn{MaBan="W10-LEGACY",KhuVucId=area.Id,SoChoNgoi=4,TrangThai=TrangThaiBan.CanDon};
        var companion=new BanAn{MaBan="W10-GROUP",KhuVucId=area.Id,SoChoNgoi=4,TrangThai=TrangThaiBan.DangPhucVu};
        db.BanAn.AddRange(legacyTable,companion);await db.SaveChangesAsync();
        var stale=Booking("W10-STALE",today.Date.AddDays(-3).AddHours(18),TrangThaiDatBan.DaNhanBan);
        stale.ThoiDiemNhanBan=stale.GioDen;stale.Ban.Add(new(){BanAnId=legacyTable.Id});stale.Ban.Add(new(){BanAnId=companion.Id});db.DatBan.Add(stale);await db.SaveChangesAsync();
        var staleBill=new HoaDon{MaHoaDon="W10-STALE-BILL",DatBanId=stale.Id,NhanVienId=staff.Id,ThoiDiemLap=stale.GioDen,TrangThai=TrangThaiHoaDon.ChuaThanhToan,TongTienHang=100000};
        db.HoaDon.Add(staleBill);await db.SaveChangesAsync();
        check((await service.PhysicalBusyTables(DateTimeOffset.UtcNow)).Contains(legacyTable.Id),"Legacy physical flags require explicit staff confirmation today");
        check(!(await service.PhysicalBusyTables(TableService.VietnamTime(evening))).Contains(legacyTable.Id),"Legacy physical flags never lock another calendar date");
        check(!(await new OrderService(db).GetOccupiedTablesAsync()).Any(x=>x.Id==companion.Id),"POS excludes past-day services and orphan physical flags");
        var pendingHtml=System.Net.WebUtility.HtmlDecode(await Get(admin,"/SoDoBan"));
        check(pendingHtml.Contains($"data-service-review=\"{stale.Id}\"")&&pendingHtml.Contains("Chờ xác nhận hoàn tất"),"Past service remains actionable on the board instead of being hidden or labelled cleaning forever");
        check(await service.CompleteService(stale.Id,Version(stale)) is not null,"Old unpaid service cannot be silently cleared");
        await db.Entry(stale).ReloadAsync();check(stale.ThoiDiemKetThuc is null,"Unpaid old bill retains service history unchanged");
        staleBill.TrangThai=TrangThaiHoaDon.DaThanhToan;await db.SaveChangesAsync();
        var staleVersion=Version(stale);
        check(await Post(admin,"/SoDoBan/HoanTatLuot",pendingHtml,new(){["id"]=stale.Id.ToString(),["rowVersion"]=staleVersion})==HttpStatusCode.Redirect,"Staff completes an old grouped service through the board endpoint");
        await db.Entry(stale).ReloadAsync();await db.Entry(legacyTable).ReloadAsync();await db.Entry(companion).ReloadAsync();
        check(stale.ThoiDiemKetThuc is not null&&legacyTable.TrangThai==TrangThaiBan.SanSang&&companion.TrangThai==TrangThaiBan.SanSang,"One confirmation makes all linked old tables ready without a cleaning stage");
        check(await service.CompleteService(stale.Id,staleVersion) is not null,"Stale booking version cannot complete a party again");
        legacyTable.TrangThai=TrangThaiBan.CanDon;await db.SaveChangesAsync();
        check(await service.ChangeTable(legacyTable.Id,Version(legacyTable),true) is null,"Legacy completed-but-dirty data can be explicitly reconciled without touching its receipt");

        var old=Booking("W10-OLD-PAPERWORK",today.Date.AddDays(-2).AddHours(18),TrangThaiDatBan.DaNhanBan);
        old.ThoiDiemNhanBan=old.GioDen;old.Ban.Add(new(){BanAnId=legacyTable.Id});db.DatBan.Add(old);await db.SaveChangesAsync();
        var current=Booking("W10-CURRENT-PARTY",today.Date.AddHours(18),TrangThaiDatBan.DaNhanBan);
        current.GioDen=TableService.VietnamTime(today.Date.AddMinutes(1));current.GioKetThucDuKien=TableService.VietnamTime(today.Date.AddDays(1));
        current.ThoiDiemNhanBan=DateTimeOffset.UtcNow;current.Ban.Add(new(){BanAnId=legacyTable.Id});legacyTable.TrangThai=TrangThaiBan.DangPhucVu;db.DatBan.Add(current);await db.SaveChangesAsync();
        var paidOld=new HoaDon{MaHoaDon="W10-OLD-PAID",DatBanId=old.Id,NhanVienId=staff.Id,ThoiDiemLap=old.GioDen,TrangThai=TrangThaiHoaDon.DaThanhToan};db.HoaDon.Add(paidOld);await db.SaveChangesAsync();
        await service.CompletePaidService(old.Id);await db.Entry(old).ReloadAsync();await db.Entry(legacyTable).ReloadAsync();
        check(old.ThoiDiemKetThuc is not null&&legacyTable.TrangThai==TrangThaiBan.DangPhucVu,"Reconciling paid old paperwork never releases a newer party on the same table");
        check((await new OrderService(db).GetOccupiedTablesAsync()).Single(x=>x.Id==legacyTable.Id).DatBanId==current.Id,"POS selects the current day's exact party after resolving old paperwork");
    }
}
